<?php
declare(strict_types=1);

function nzmaint_referenced_media(array $db): array {$keep=[];foreach($db['posts']??[]as$p){foreach((array)($p['images']??[])as$f){$b=basename((string)$f);if($b!=='')$keep[$b]=true;}$v=basename((string)($p['video']??''));if($v!=='')$keep[$v]=true;}return$keep;}
function nzmaint_cleanup_media(array $db): array {$dir=__DIR__.'/marketplace-uploads';if(!is_dir($dir))return['deleted'=>0,'bytes'=>0];$keep=nzmaint_referenced_media($db);$deleted=0;$bytes=0;$cut=time()-48*3600;foreach(glob($dir.'/*')?:[]as$f){if(!is_file($f))continue;$base=basename($f);if($base==='.htaccess'||isset($keep[$base])||filemtime($f)>$cut)continue;$size=(int)filesize($f);if(@unlink($f)){$deleted++;$bytes+=$size;}}return['deleted'=>$deleted,'bytes'=>$bytes];}
function nzmaint_cleanup_geocode_cache(): int {$dir=__DIR__.'/.marketplace-data/geocode-cache';if(!is_dir($dir))return 0;$n=0;$cut=time()-30*86400;foreach(glob($dir.'/*.json')?:[]as$f)if(is_file($f)&&filemtime($f)<$cut&&@unlink($f))$n++;return$n;}
function nzmaint_prune_data(): array {
    $stats=['notifications'=>0,'messages'=>0,'privacy_anonymized'=>0];$now=time();
    nzc_db_write(function(&$db)use(&$stats,$now){
        $before=count($db['notifications']??[]);$db['notifications']=array_values(array_filter($db['notifications']??[],function($n)use($now){$ts=strtotime((string)($n['created_at']??''))?:$now;return empty($n['read'])||$ts>$now-180*86400;}));$stats['notifications']=$before-count($db['notifications']);
        $activeConvs=[];foreach($db['conversations']??[]as$c)if(!empty($c['id']))$activeConvs[(string)$c['id']]=true;$before=count($db['messages']??[]);$db['messages']=array_values(array_filter($db['messages']??[],function($m)use($activeConvs,$now){$cid=(string)($m['conversation_id']??'');$ts=strtotime((string)($m['created_at']??''))?:$now;if($ts<=$now-365*86400)return false;return isset($activeConvs[$cid])||$ts>$now-30*86400;}));$stats['messages']=$before-count($db['messages']);
        foreach($db['users']??[]as&$u){$last=strtotime((string)($u['last_seen_at']??$u['last_login']??$u['created_at']??''))?:$now;if($last>$now-90*86400)continue;$had=!empty($u['last_ip'])||!empty($u['last_user_agent'])||!empty($u['last_device']);unset($u['last_ip'],$u['last_user_agent'],$u['last_device']);if($had)$stats['privacy_anonymized']++;}unset($u);
    });return$stats;
}
function nzmaint_rate_cleanup(): int {$file=__DIR__.'/.marketplace-data/rate-limit.json';if(!is_file($file))return 0;$raw=@file_get_contents($file);$data=json_decode($raw?:'',true);if(!is_array($data))return 0;$now=time();$before=count($data);foreach($data as$k=>$vals){$keep=array_values(array_filter((array)$vals,fn($t)=>is_int($t)&&$t>$now-86400));if($keep)$data[$k]=$keep;else unset($data[$k]);}nzstore_atomic_json($file,$data);return$before-count($data);}
function nzmaint_storage_stats(): array {$dir=__DIR__.'/marketplace-uploads';$used=0;$files=0;foreach(glob($dir.'/*')?:[]as$f)if(is_file($f)&&basename($f)!=='.htaccess'){$files++;$used+=(int)filesize($f);}$free=@disk_free_space(__DIR__);return['media_files'=>$files,'media_bytes'=>$used,'disk_free_bytes'=>is_numeric($free)?(int)$free:null];}
function nzmaint_run(): array {
    $life=function_exists('nzl_tick')?nzl_tick(true):[];$db=nzc_db_read();$media=nzmaint_cleanup_media($db);$pruned=nzmaint_prune_data();$backup=nzstore_backup(nzc_default_db());$rate=nzmaint_rate_cleanup();$geocode=nzmaint_cleanup_geocode_cache();$storage=nzmaint_storage_stats();$integrity='unknown';$pdo=nzstore_sqlite();if($pdo){try{$integrity=(string)$pdo->query('PRAGMA integrity_check')->fetchColumn();}catch(Throwable $e){$integrity='error';}}
    nzstore_audit('system-cron','maintenance','system','',['lifecycle'=>$life,'media'=>$media,'pruned'=>$pruned,'backup'=>$backup,'rate_keys_removed'=>$rate,'geocode_cache_removed'=>$geocode,'storage'=>$storage,'integrity'=>$integrity]);return['lifecycle'=>$life,'media'=>$media,'pruned'=>$pruned,'backup'=>$backup,'rate_keys_removed'=>$rate,'geocode_cache_removed'=>$geocode,'storage'=>$storage,'integrity'=>$integrity,'backend'=>nzstore_backend(),'checked_at'=>date('c')];
}